<script setup>
import{computed,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{UploadFilled,MagicStick,Check}from'@element-plus/icons-vue';import api,{errorText,unwrap}from'../api'
const text=ref(''),tasks=ref([]),methods=ref(['WBS']),confirmed=ref(false),loading=ref(false),publishing=ref(false),warning=ref(''),source=ref(null),view=ref('cards'),fileName=ref('')
const options=[['四象限法','重要度与紧急度'],['WBS','工作包与交付物'],['KANO','需求价值分层'],['RICE','影响与成本评分'],['关键路径法','依赖与关键工期'],['SMART','可衡量目标'],['PDCA','闭环持续改进'],['5W2H','执行要素完整化']]
const sourceMeta=computed(()=>({meeting:['会议材料','会议任务','会议行动项','会议导入'],project:['项目材料','项目工作','待命名项目','项目资料导入'],daily:['日常材料','日常工作','日常工作','日常资料导入']}[source.value?.type]||['待识别','','','']))
const selected=computed(()=>tasks.value.filter(t=>t.selected&&!t.published&&!t.duplicate))
async function upload(o){const fd=new FormData();fd.append('file',o.file);try{const d=unwrap(await api.post('/file/upload',fd));text.value=d.content;fileName.value=d.fileName;confirmed.value=false}catch(e){ElMessage.error(errorText(e))}}
async function confirm(){await ElMessageBox.confirm('请确认手机号、证件号、邮箱、地址、密码及密钥等敏感信息均已隐藏。','脱敏人工复核',{confirmButtonText:'确认脱敏无误',type:'warning'});confirmed.value=true}
async function split(){if(text.value.trim().length<10)return ElMessage.warning('请至少输入10个字');if(!confirmed.value)return ElMessage.warning('请先确认脱敏');loading.value=true;try{const d=unwrap(await api.post('/task/split',{text:text.value,methods:methods.value}));source.value={type:d.sourceType,confidence:d.sourceConfidence,reason:d.sourceReason};const m=({meeting:['meeting','会议行动项','会议导入'],project:['project','待命名项目','项目资料导入'],daily:['daily','日常工作','日常资料导入']})[d.sourceType];tasks.value=d.tasks.map((t,i)=>({...t,workCategory:m[0],projectName:m[1],source:m[2],startTime:`${String(9+i).padStart(2,'0')}:00`,endTime:`${String(10+i).padStart(2,'0')}:00`,selected:true}));warning.value=d.warning||''}catch(e){ElMessage.error(errorText(e))}finally{loading.value=false}}
async function publish(){publishing.value=true;try{const d=unwrap(await api.post('/tasks/bulk',{tasks:selected.value.map(t=>({...t,assigneeId:1}))}));const p=new Set(d.published.map(t=>t.title)),x=new Set(d.duplicates.map(t=>t.title));tasks.value.forEach(t=>{if(p.has(t.title))t.published=true;if(x.has(t.title))t.duplicate=true});ElMessage.success(`发布 ${d.published.length} 项，跳过 ${d.duplicates.length} 项`)}catch(e){ElMessage.error(errorText(e))}finally{publishing.value=false}}
</script>
<template><div class="page smartx"><div class="page-title"><div><p class="eyebrow">AI TASK STRUCTURING</p><h1>智能识别与科学拆解</h1><p>AI自动判断材料来源，并以多种结构展示可执行任务</p></div></div><div class="smartx-grid"><section class="sx-input"><header><h2>1. 导入与脱敏确认</h2><p>来源类型无需选择，拆解时由AI识别</p></header><el-upload drag :show-file-list="false" :http-request="upload"><UploadFilled/><div>拖拽文件或<em>选择文件</em></div></el-upload><span v-if="fileName" class="file-name"><Check/>{{fileName}}</span><el-input v-model="text" type="textarea" :rows="8" placeholder="粘贴会议纪要、项目资料、工作安排等内容" @input="confirmed=false"/><div class="confirm-row" :class="{ok:confirmed}"><span>{{confirmed?'脱敏已人工确认':'拆解前必须确认脱敏结果'}}</span><el-button :type="confirmed?'success':'warning'" plain @click="confirm">{{confirmed?'重新确认':'检查并确认'}}</el-button></div><header><h2>2. 选择科学方法</h2><p>可以组合多个方法提升拆解质量</p></header><el-checkbox-group v-model="methods" class="method-grid"><el-checkbox v-for="o in options" :key="o[0]" :value="o[0]"><b>{{o[0]}}</b><small>{{o[1]}}</small></el-checkbox></el-checkbox-group><el-button class="split-btn" type="primary" :icon="MagicStick" :loading="loading" @click="split">AI识别来源并拆解</el-button></section><section class="sx-result"><header><div><h2>3. 结构化任务</h2><p v-if="source">识别为 {{sourceMeta[0]}} · 置信度 {{source.confidence}}% · {{source.reason}}</p><p v-else>拆解后可切换卡片、表格和思维导图</p></div><div><el-segmented v-model="view" :options="[{label:'卡片',value:'cards'},{label:'表格',value:'table'},{label:'思维导图',value:'mind'}]"/><el-button v-if="tasks.length" type="primary" :loading="publishing" :disabled="!selected.length" @click="publish">一键发布 {{selected.length}} 项</el-button></div></header><el-alert v-if="warning" :title="warning" type="warning" :closable="false"/><div v-if="tasks.length&&view==='cards'" class="task-cards"><article v-for="(t,i) in tasks" :key="i"><el-checkbox v-model="t.selected" :disabled="t.published||t.duplicate"/><div><span><el-tag>{{t.priority}}</el-tag> +{{t.points}} 积分</span><el-input v-model="t.title"/><p>{{t.description}}</p><small>{{t.method}} · {{t.dueDate}} · {{t.standard}}</small></div><el-tag v-if="t.published" type="success">已发布</el-tag><el-tag v-if="t.duplicate" type="warning">重复</el-tag></article></div><el-table v-else-if="tasks.length&&view==='table'" :data="tasks" stripe><el-table-column width="45"><template #default="s"><el-checkbox v-model="s.row.selected"/></template></el-table-column><el-table-column prop="title" label="任务" min-width="190"/><el-table-column prop="priority" label="等级" width="70"/><el-table-column prop="method" label="方法" width="100"/><el-table-column prop="dueDate" label="期限" width="110"/><el-table-column prop="points" label="积分" width="70"/></el-table><div v-else-if="tasks.length" class="mind-map"><div class="mind-root">{{sourceMeta[0]}}<small>{{methods.join(' + ')}}</small></div><div class="mind-branches"><article v-for="(t,i) in tasks" :key="i"><i></i><div><b>{{i+1}}. {{t.title}}</b><span>{{t.priority}} · {{t.method}} · +{{t.points}}分</span><small>{{t.standard}}</small></div></article></div></div><el-empty v-else description="等待AI识别与拆解"/></section></div></div></template>
<style scoped>
.smartx-grid{display:grid;grid-template-columns:390px 1fr;gap:14px}.sx-input,.sx-result{background:#fff;border:1px solid #e2e7ed;padding:18px;min-width:0}.sx-input header,.sx-result header{margin-bottom:12px}.sx-result>header{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.sx-result>header>div:last-child{display:flex;gap:8px}.smartx h2{font-size:15px;margin:0 0 4px}.smartx header p{font-size:11px;color:#8390a1;margin:0}.sx-input :deep(.el-upload-dragger){padding:17px}.sx-input :deep(.el-upload-dragger svg){width:26px;color:#087c66}.file-name{display:flex;align-items:center;gap:5px;font-size:11px;color:#087c66;margin:8px 0}.file-name svg{width:14px}.confirm-row{display:flex;justify-content:space-between;align-items:center;padding:9px;background:#fff7e8;margin:8px 0 18px;font-size:11px}.confirm-row.ok{background:#eaf6f2;color:#087c66}.method-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}.method-grid :deep(.el-checkbox){height:auto;margin:0;padding:8px;border:1px solid #e5e9ee}.method-grid b,.method-grid small{display:block}.method-grid small{font-size:9px;color:#8490a0}.split-btn{width:100%;margin-top:12px}.task-cards{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:12px}.task-cards article{display:grid;grid-template-columns:auto 1fr auto;gap:9px;border:1px solid #e3e8ed;padding:12px}.task-cards article>div>span{font-size:10px;color:#087c66}.task-cards p,.task-cards small{font-size:11px;color:#69778a;line-height:1.5}.task-cards small{display:block}.mind-map{display:grid;grid-template-columns:180px 1fr;align-items:center;min-height:420px}.mind-root{background:#087c66;color:#fff;padding:18px;text-align:center;border-radius:6px}.mind-root small{display:block;margin-top:5px}.mind-branches{border-left:2px solid #9bcfc1;padding-left:28px}.mind-branches article{position:relative;margin:10px 0}.mind-branches i{position:absolute;width:28px;border-top:2px solid #9bcfc1;left:-28px;top:50%}.mind-branches div{border:1px solid #dce6e3;padding:9px 12px;border-left:4px solid #087c66}.mind-branches span,.mind-branches small{display:block;font-size:10px;color:#788596;margin-top:4px}@media(max-width:1000px){.smartx-grid{grid-template-columns:1fr}.task-cards{grid-template-columns:1fr}}@media(max-width:600px){.method-grid{grid-template-columns:1fr}.sx-result>header{display:block}.sx-result>header>div:last-child{margin-top:9px;flex-wrap:wrap}.mind-map{grid-template-columns:1fr}.mind-branches{margin-top:20px}}
</style>

